"""Flight-surgeon style Markdown report for one astronaut on one mission day."""
from . import engine as E

WORD = {"green": "Nominal", "amber": "Watch", "red": "Act now"}


def build_report(cid: str, day: int) -> str:
    eng, person = E.member(cid), E._PEOPLE[cid]
    st = eng.status(day)
    day = st["day"]
    L = [f"# Crew health report: {person['name']} ({person['role']})",
         f"Mission day {day} of {E.N_DAYS}. Link delay about {E.link_delay_min(day)} min. "
         "Generated by AstroTwin from simulated or imported data. Decision support only, not a diagnosis.", ""]
    if st["calibrating"]:
        return "\n".join(L + [f"Baseline still being learned (day {day + 1} of {E.BASELINE_DAYS})."])
    L += [f"**Readiness {st['readiness']}/100, overall {WORD[st['overall']]}.**", "",
          "| Domain | Status | Trend | Projection |", "|---|---|---|---|"]
    for v in st["domains"].values():
        f = v["forecast"]
        proj = f"reaches {f['eta']['level']} in about {f['eta']['days']} days" if f and f["eta"] else "none within 30 days"
        L.append(f"| {v['label']} | {WORD[v['level']]} | {f['trend'] if f else 'n/a'} | {proj if f else 'n/a'} |")
    L.append("")
    for v in st["domains"].values():
        if v["level"] == "green":
            continue
        L += [f"## {v['label']}: {WORD[v['level']]}", "**Why it flagged**"] + [f"- {r}" for r in v["reasons"]]
        if v["goals"]:
            L += ["**Recovery goals**"] + [f"- {g}" for g in v["goals"]]
        L += ["**Suggested actions (illustrative)**"] + [f"- {a}" for a in v["actions"]]
        L += [f"- Note: {a}" for a in v["attribution"]] + [""]
    first = max(0, day - 13)
    L += ["## Last 14 days", "| Day | " + " | ".join(m for m in E.METRICS) + " |",
          "|---|" + "---|" * len(E.METRICS)]
    for d in range(first, day + 1):
        L.append(f"| {d} | " + " | ".join(f"{eng.df[m].iloc[d]:.1f}" for m in E.METRICS) + " |")
    L += ["", "Baseline (first 14 days): " + ", ".join(f"{m} {eng.mean[m]:.1f}" for m in E.METRICS)]
    q = [m for m in E.earth_queue(day) if m["crew_id"] == cid]
    if q:
        L += ["", "## Messages queued to Earth"] + [f"- Day {m['day']}: {m['domain']} {WORD[m['level']].lower()} ({m['priority']})" for m in q]
    return "\n".join(L) + "\n"
